@pytest.mark.parametrize('text,expected_dict,expected_list', ROOTS)
def test_roots_match_sympy(text, expected_dict, expected_list):
    p = sx.sympify(text, locals=NS)
    assert str(sx.roots(p, x)) == expected_dict
    assert str(sx.roots(p, x, multiple=True)) == expected_list


@pytest.mark.parametrize('text,expected', SIMPLIFY)
def test_simplify_rationalizes_sum_denominators(text, expected):
    e = sx.sympify(text, locals=NS)
    assert str(sx.simplify(e)) == expected


def test_native_denominator_step():
    e = sx.sympify('(2 + sqrt(5))/(50*(1 + sqrt(5)))')
    assert str(_core._st_simplify_rationalize_denominator(e)) == 'sqrt(5)/200 + 3/200'
    kept = sx.sympify('x/(sqrt(2) + sqrt(3))', locals=NS)
    assert _core._st_simplify_rationalize_denominator(kept) == kept


@pytest.mark.parametrize('text,expected', EXPAND)
def test_expand_repeats_until_fixed_point(text, expected):
    assert str(sx.expand(sx.sympify(text, locals=NS))) == expected


def _assert_primitive(integrand, primitive):
    derivative = sx.diff(primitive, x) - integrand
    with mpmath.workdps(30):
        for point in ('0.3', '1.7', '-2.2'):
            value = complex(sx.N(derivative.subs(x, sx.Rational(point)), 30))
            assert abs(value) < 1e-20, (point, value)


CARDANO_GAP = {'1/(x**3 + x + 1)', '1/(x**3 + 2*x - 1)'}


@pytest.mark.parametrize('text', sorted(INTEGRATE))
def test_integrate_matches_sympy(text):
    f = sx.sympify(text, locals=NS)
    result = sx.integrate(f, x)
    _assert_primitive(f, result)
    if text in CARDANO_GAP:
        # Known form gap (docs/algorithmic-parity.md, exroots): the native EX
        # simplify does not reach SymPy's normal form of the Cardano
        # radicals; the primitive is exact and shorter than SymPy's.
        assert len(str(result)) <= len(INTEGRATE[text])
        return
    assert str(result) == INTEGRATE[text]
